            if x <= 0:
                return 0

            sx = str(x)
            n = len(sx)
            ls = len(s)
            s_val = int(s)
            if x < s_val:
                return 0

            # precompute powers of (limit+1)
            max_l = n - ls
            pow_lim = [1] * (max_l + 1)
            for i in range(1, max_l + 1):
                pow_lim[i] = pow_lim[i - 1] * (limit + 1)

            def all_count_l(l):
                if l == 0:
                    return 1  # only the number exactly equal to s
                return limit * pow_lim[l - 1]

            def count_l_leq(U, l):
                """Count l-digit numbers with digits<=limit, no leading zero, <= U."""
                if l == 0:
                    return 1 if U >= 0 else 0
                if U < 10 ** (l - 1):
                    return 0
                su = str(U)
                lu = len(su)
                if lu > l:
                    return all_count_l(l)
                if lu < l:
                    return 0

                dp_tight = 1
                dp_loose = 0
                for pos in range(l):
                    curr = int(su[pos])
                    new_tight = 0
                    new_loose = 0

                    # transitions from tight state
                    if pos == 0:
                        low_d = 1
                    else:
                        low_d = 0
                    high_d = min(limit, curr)
                    if dp_tight and low_d <= high_d:
                        for d in range(low_d, high_d + 1):
                            if d == curr:
                                new_tight += dp_tight
                            else:
                                new_loose += dp_tight

                    # transitions from loose state
                    if dp_loose:
                        if pos == 0:
                            new_loose += dp_loose * limit
                        else:
                            new_loose += dp_loose * (limit + 1)

                    dp_tight, dp_loose = new_tight, new_loose

                return dp_tight + dp_loose

            result = 0

            # lengths smaller than n: automatically < x
            for m in range(ls, n):
                l = m - ls
                result += all_count_l(l)

            # length equal to n: need to respect upper bound x
            # number form: prefix (length l) concatenated with s
            # value = prefix * 10^ls + s_val
            for m in [n]:
                l = m - ls
                pow10_ls = 10 ** ls
                max_prefix = (x - s_val) // pow10_ls
                if max_prefix < 0:
                    break
                if l == 0:
                    # number is exactly s
                    if s_val <= x:
                        result += 1
                else:
                    result += count_l_leq(max_prefix, l)

            return result

        return count(finish) - count(start - 1)
```

